import React, { useState, useEffect } from 'react';
import './index.css';
import Overview  from './pages/Overview';
import Teams     from './pages/Teams';
import Players   from './pages/Players';
import Upcoming  from './pages/Upcoming';
import Predictor from './pages/Predictor';

const TABS = [
  { id: 'overview',  label: '📊 Overview'  },
  { id: 'teams',     label: '⚔️ Teams'     },
  { id: 'players',   label: '🏅 Players'   },
  { id: 'upcoming',  label: '📅 Upcoming'  },
  { id: 'predictor', label: '🔮 Predictor' },
];

export default function App() {
  const [active, setActive] = useState('overview');
  const [theme, setTheme] = useState(() => {
    return localStorage.getItem('theme') || 'light';
  });

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', theme);
    localStorage.setItem('theme', theme);
  }, [theme]);

  const page = {
    overview:  <Overview />,
    teams:     <Teams />,
    players:   <Players />,
    upcoming:  <Upcoming />,
    predictor: <Predictor />,
  }[active];

  return (
    <div className="app">
      {/* Header */}
      <header className="header">
        <div className="header-brand">
          <div className="header-logo">🏆</div>
          <div>
            <div className="header-title">Sports Analytics</div>
            <div className="header-sub">Cricket &amp; Football · 2022–2026</div>
          </div>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: '16px' }}>
          <nav className="nav-tabs">
            {TABS.map(t => (
              <button
                key={t.id}
                className={`nav-tab${active === t.id ? ' active' : ''}`}
                onClick={() => setActive(t.id)}
              >
                {t.label}
              </button>
            ))}
          </nav>
          <button
            className="theme-toggle"
            onClick={() => setTheme(prev => prev === 'light' ? 'dark' : 'light')}
            title={`Switch to ${theme === 'light' ? 'dark' : 'light'} mode`}
            aria-label="Toggle theme"
          >
            {theme === 'light' ? '🌙' : '☀️'}
          </button>
        </div>
      </header>

      {/* Page content */}
      <main className="container">{page}</main>

      {/* Footer */}
      <footer style={{ textAlign: 'center', padding: '1.5rem', fontSize: 12, color: 'var(--muted)', borderTop: '1px solid var(--border)', background: 'var(--surface)', marginTop: 'auto' }}>
        Sports Analytics Dashboard · React + Node.js · Data: 2022–2026
      </footer>
    </div>
  );
}
